        self.buildtrie(words)
        results = []
        for j, word in enumerate(words):
            node = self.trie
            for i in range(len(word)):
                if 'idx' in node:
                    if node['idx']!=j:
                        rest = word[i:]
                        if rest=="".join(reversed(rest)):
                            results.append([j, node['idx']])
                c = word[i]
